<script setup lang="ts">
import {onBeforeUnmount,onMounted,ref} from 'vue'
import {useWorkspace} from '../../app/workspace'
import {createLatestRequests,isCancelled} from '../../shared/api/client'
import FormDialog from '../../shared/components/FormDialog.vue'
import Pagination from '../../shared/components/Pagination.vue'
import {formatTimestamp} from '../../shared/time'
type Transfer={id:string;person_id:string;name:string;document_mask:string;source_org_id:string;target_org_id:string;source_org:string;target_org:string;reason:string;response_note:string;status:string;version:number;created_at:string}
const {api,command,captureSession}=useWorkspace(),requests=createLatestRequests(api)
const rows=ref<Transfer[]>([]),page=ref(1),total=ref(0),orgId=ref(''),busy=ref(false),error=ref(''),notice=ref(''),selected=ref<Transfer|null>(null),action=ref('ACCEPT'),note=ref('')
const labels:Record<string,string>={PENDING:'待接收',ACCEPTED:'已接收',REJECTED:'已退回',CANCELLED:'已撤销'}
async function load(target=page.value){busy.value=true;error.value='';try{const [result,options]=await Promise.all([requests.latest<{items:Transfer[];total:number}>('list',`/person-drafts/transfers/inbox?page=${target}`),requests.latest<{current_org_id:string}>('options','/person-drafts/transfers/options')]);rows.value=result.items;total.value=result.total;page.value=target;orgId.value=options.current_org_id}catch(e){if(!isCancelled(e))error.value=e instanceof Error?e.message:'移交记录加载失败'}finally{busy.value=false}}
async function resolve(){if(!selected.value)return;busy.value=true;error.value='';const valid=captureSession();try{await command('person-transfer-resolve-'+selected.value.id,`/person-drafts/transfers/${selected.value.id}/resolve`,{version:selected.value.version,action:action.value,note:note.value});if(!valid())return;selected.value=null;notice.value='移交处理已记录';await load()}catch(e){if(!isCancelled(e))error.value=e instanceof Error?e.message:'处理失败'}finally{busy.value=false}}
onMounted(()=>{void load(1)});onBeforeUnmount(()=>requests.dispose())
</script>
<template><section class="card"><p v-if="error&&!selected" class="error" role="alert">{{error}}</p><p v-if="notice" class="success" role="status">{{notice}}</p><div class="page-toolbar"><p class="muted person-hint">待接收阶段仅显示姓名、脱敏证件和移交原因；确认后才取得当前主档、在执行措施及待办的办理范围。</p><button class="secondary" :disabled="busy" @click="load()">刷新交接</button></div><div class="table-wrap"><table><thead><tr><th class="row-number">序号</th><th>姓名</th><th>脱敏证件</th><th>移出单位</th><th>接收单位</th><th>状态</th><th>发起时间</th><th>操作</th></tr></thead><tbody><tr v-for="(row,index) in rows" :key="row.id"><td class="row-number">{{(page-1)*20+index+1}}</td><td>{{row.name}}</td><td>{{row.document_mask}}</td><td>{{row.source_org}}</td><td>{{row.target_org}}</td><td>{{labels[row.status]}}</td><td>{{formatTimestamp(row.created_at)}}</td><td><button class="link" @click="selected=row;action=row.target_org_id===orgId?'ACCEPT':'CANCEL';note='';error=''">{{row.status==='PENDING'?'办理':'查看'}}</button></td></tr></tbody></table><p v-if="!rows.length&&!busy" class="empty">暂无管辖交接记录</p></div><Pagination :page="page" :total="total" :loading="busy" @change="load($event)"/><FormDialog v-if="selected" title="办理人员交接" :busy="busy" :error="error" @close="selected=null"><p>{{selected.name}} · {{selected.document_mask}}</p><p>{{selected.source_org}} → {{selected.target_org}}</p><p class="person-text">移交原因：{{selected.reason}}</p><p v-if="selected.response_note" class="person-text">处理意见：{{selected.response_note}}</p><form v-if="selected.status==='PENDING'" @submit.prevent="resolve"><label>处理动作<select v-model="action"><template v-if="selected.target_org_id===orgId"><option value="ACCEPT">接收责任</option><option value="REJECT">退回核对</option></template><option v-else value="CANCEL">撤销申请</option></select></label><label>处理意见<textarea v-model="note" maxlength="2000" required></textarea></label><p class="muted person-hint">接收后转入当前待执行/执行措施和未完成待办，不自动移交原单位全部案件或检测历史；不会自动合并同名档案。</p><button :disabled="busy">确认处理</button></form></FormDialog></section></template>
